    #[cfg(all(target_arch = "x86_64", unix))]
    #[test]
    fn native_sigsegv_recovery_epilogue_returns_to_run_native_boundary() {
        let _lock = super::super::heap_test_lock()
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        egcl_rt::install_signal_handlers().unwrap();
        egcl_rt::runtime::set_sigsegv_null_guard_recovery_ip(
            native_sigsegv_recovery_epilogue as *const () as usize,
        );

        let code = [
            0x41, 0x56, // push r14
            0x41, 0x57, // push r15
            0x41, 0x54, // push r12 (matches the native recovery epilogue)
            0x31, 0xC0, // xor eax, eax
            0x48, 0x89, 0x00, // mov [rax], rax => null-guard SIGSEGV
        ];
        let buf = egcl_rt::jit::JitBuffer::new(&code).unwrap();
        let entry = buf.as_ptr();
        let f: extern "C" fn() -> u64 = unsafe { std::mem::transmute(entry) };

        let ret = f();
        egcl_rt::runtime::set_sigsegv_null_guard_recovery_ip(0);

        assert_eq!(ret, egcl_rt::value::NIL_BITS);
        assert!(egcl_rt::runtime::check_sigsegv_null_guard());
    }

    #[cfg(all(target_arch = "x86_64", unix))]
    #[test]
    fn run_native_rewrites_null_guard_sigsegv_to_type_error() {
        let _lock = super::super::heap_test_lock()
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        egcl_rt::install_signal_handlers().unwrap();
        let _ = egcl_rt::runtime::check_sigsegv_null_guard();

        let code = [
            0x41, 0x56, // push r14
            0x41, 0x57, // push r15
            0x41, 0x54, // push r12 (matches the native recovery epilogue)
            0x31, 0xC0, // xor eax, eax
            0x48, 0x89, 0x00, // mov [rax], rax => null-guard SIGSEGV
        ];
        let buf = egcl_rt::jit::JitBuffer::new(&code).unwrap();
        let entry = buf.as_ptr();
        let code_info = install_stack_map(1, std::sync::Weak::new()).unwrap();
        let nc = NativeCode {
            _env_names: Box::default(),
            _call_cells: Vec::new(),
            _storage: NativeCodeStorage::Checked { _buffer: buf },
            body: None,
            transfer_abi_version: NATIVE_TRANSFER_ABI_VERSION,
            transfer_abi_arch: NATIVE_TRANSFER_ARCH,
            _direct_calls: Vec::new(),
            entry,
            code_len: code.len(),
            is_t2: false,
            num_slots: 1,
            compiled_entry: 0,
            code_id: 0,
            osr_entries: HashMap::new(),
            bcp_offsets: vec![],
            code_info,
            has_deopt: false,
            t2_metadata: None,
        };
        assert!(native_transfer_abi_compatible(&nc));
        let mut env = Env::new(false);

        let error = run_native(&nc, u32::MAX, &[], &mut env).unwrap_err();
        let mut legacy = nc;
        legacy.transfer_abi_version = 0;
        assert!(!native_transfer_abi_compatible(&legacy));
        legacy.transfer_abi_version = NATIVE_TRANSFER_ABI_VERSION;
        legacy.transfer_abi_arch = 0;
        assert!(!native_transfer_abi_compatible(&legacy));

        assert!(matches!(
            error.without_backtrace(),
            EgclError::TypeError {
                datum,
                expected
            } if *datum == NIL && expected == "non-null object reference"
        ));
        let trace = error
            .backtrace()
            .expect("capture native fault before frame teardown");
        assert_eq!(trace[0].origin, egcl_rt::debug_stack::FrameOrigin::Managed);
    }

    #[cfg(all(target_arch = "x86_64", unix))]
    #[test]
    fn run_native_rewrites_stack_guard_sigsegv_to_stack_overflow() {
        let _lock = super::super::heap_test_lock()
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        egcl_rt::install_signal_handlers().unwrap();
        let _ = egcl_rt::runtime::check_sigsegv_stack_guard();

        let guard = egcl_rt::current_thread()
            .stack()
            .guard_base()
            .expect("current thread stack must have a registered guard page")
            as u64;
        let mut code = vec![
            0x41, 0x56, // push r14
            0x41, 0x57, // push r15
            0x41, 0x54, // push r12 (matches the native recovery epilogue)
            0x48, 0xB8, // mov rax, guard
        ];
        code.extend_from_slice(&guard.to_le_bytes());
        code.extend_from_slice(&[0x48, 0x89, 0x00]); // mov [rax], rax
        let buf = egcl_rt::jit::JitBuffer::new(&code).unwrap();
        let entry = buf.as_ptr();
        let code_info = install_stack_map(1, std::sync::Weak::new()).unwrap();
        let nc = NativeCode {
            _env_names: Box::default(),
            _call_cells: Vec::new(),
            _storage: NativeCodeStorage::Checked { _buffer: buf },
            body: None,
            transfer_abi_version: NATIVE_TRANSFER_ABI_VERSION,
            transfer_abi_arch: NATIVE_TRANSFER_ARCH,
            _direct_calls: Vec::new(),
            entry,
            code_len: code.len(),
            is_t2: false,
            num_slots: 1,
            compiled_entry: 0,
            code_id: 0,
            osr_entries: HashMap::new(),
            bcp_offsets: vec![],
            code_info,
            has_deopt: false,
            t2_metadata: None,
        };
        let mut env = Env::new(false);

        let error = run_native(&nc, u32::MAX, &[], &mut env).unwrap_err();

        assert!(matches!(error, EgclError::StackOverflow(_)));
    }

    #[cfg(all(target_arch = "x86_64", unix))]
    #[test]
    fn c2i_helper_calls_disable_native_sigsegv_recovery_around_rust_frame() {
        let mut asm = Asm::new();
        emit_c2i_helper_call(&mut asm);
        let code = asm.finish().unwrap();

        assert_eq!(
            code.windows(2)
                .filter(|bytes| *bytes == [0xFF, 0xD0])
                .count(),
            4
        );
        assert!(
            code.windows(5).any(|bytes| bytes == [0xBF, 0, 0, 0, 0]),
            "helper call must clear native SIGSEGV recovery before crossing into Rust"
        );
        assert!(
            code.windows(5).any(|bytes| bytes == [0xBF, 1, 0, 0, 0]),
            "helper call must restore native SIGSEGV recovery after returning from Rust"
        );
    }

