        egcl_rt::rooted!(bits = reader::read_from_string("#*101").unwrap().0);
        egcl_rt::rooted!(circle = arena_cons(NIL, *bits));
        super::super::store_cons_field(*circle, *circle, true).unwrap();
        assert!(pool.value(*circle).is_none());
